use std::io::{self, Read};

/// Subtraction-based GCD for strictly positive integers.
/// Terminates because (a + b) strictly decreases while staying positive.
fn gcd_i(m: u128, n: u128) -> u128 {
    debug_assert!(m > 0 && n > 0);

    let mut a = m;
    let mut b = n;

    while a != b {
        if a > b {
            // a-b is still >= 1 because a > b >= 1
            a -= b;
        } else {
            // b-a is still >= 1 because b > a >= 1
            b -= a;
        }
    }

    a
}

fn main() {
    // Read all stdin, expecting two positive integers separated by whitespace.
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let m: u128 = it.next().expect("missing first integer").parse().expect("invalid integer");
    let n: u128 = it.next().expect("missing second integer").parse().expect("invalid integer");

    assert!(m > 0 && n > 0, "inputs must be strictly positive");

    let d = gcd_i(m, n);
    println!("{d}");
}